python3 -c "
from sympy import factorint
def divisors(n):
    return sorted([i for i in range(1,n+1) if n%i==0])
for n in [2,3,4,5,6,8,9,12,16,18,25,30,36,60,120,210]:
    ds=divisors(n); k=len(ds)
    d=sum(ds[i]*ds[i+1] for i in range(k-1))
    print(f'n={n} divisors={ds} d={d} n^2={n*n} d|n^2={n*n%d==0} d/n^2={d/n/n:.4f} factor(d)={factorint(d)} factor(n)={factorint(n)}')
"

