from sympy import isprime
def divisors(n):
    return sorted([i for i in range(1,n+1) if n%i==0])
# Check if d/n is ever integer for composite n
for n in range(4, 10000):
    if isprime(n): continue
    ds=divisors(n); k=len(ds)
    d=sum(ds[i]*ds[i+1] for i in range(k-1))
    if d % n == 0:
